  /\ rw_cells rsegs m s (SvcHdrCells (sch_hdr S))
  /\ rw_cells rsegs m (s + 48) [CB 2 [b8 0; b8 0]; CB 6 j50]
  /\ rw_cells rsegs m (s + 56) [CB 8 jm]
  /\ PMutex m (s + 64) (sch_lk S)
  /\ rw_cells rsegs m (s + 104) [C4 (wz 0); CB 1 [b8 1]; CB 3 j109]
  /\ rw_cells rsegs m (s + 112) [CB 8 je]
  /\ PCond m (s + 120) CLOCK_MONOTONIC
  /\ rw_cells rsegs m (s + 168)
       [C8 (wz 0); C8 (wz 0); C8 (wz P_SCHED_GET_DEFAULT_TASK); C8 (wz 0); C8 (wz 0); C4 (wz 0); CB 4 jt;
        CB 3 [b8 1; b8 (sch_stopped S); b8 (sch_shutdown S)]; CB 5 j219; C8 (wz 0); C8 (wz 0); C8 (wz 0); C8 (wz u64max); C8 (wz u64max); C8 (wz 0)]
  /\ rw_cells rsegs m (s + 272) (CookieCells j7)
  /\ sv_vptr (sch_hdr S) = VP_SCHED /\ sv_destroy (sch_hdr S) = P_DESTROY_ALLOC_SCHED
  /\ (sch_stopped S = 0 \/ sch_stopped S = 1) /\ (sch_shutdown S = 0 \/ sch_shutdown S = 1).
Proof.
  intros LB m s S (p & j50 & jm & j109 & je & jt & j219 & j7 & IN & C0 & C1 & C2 & PM & C3 & C4 & PC & C5 & C6 & E).
  exists p, j50, jm, j109, je, jt, j219, j7.
  unfold NEWSZ_SCH, SZ_SCH, O_SCH_ONE_THREAD, O_SCH_MUTEX, O_SCH_PMUTEX, O_SCH_SPIN, O_SCH_EVENT, O_SCH_COND, O_SCH_EVSTATE in *.
  repeat (split; [assumption|]). exact E.
Qed.

Lemma Scheduler_close : forall LB m s S p j50 jm j109 je jt j219 j7,
  In (p, s, 287) LB ->
  rw_cells rsegs m s (SvcHdrCells (sch_hdr S)) ->
  rw_cells rsegs m (s + 48) [CB 2 [b8 0; b8 0]; CB 6 j50] ->
  rw_cells rsegs m (s + 56) [CB 8 jm] ->
  PMutex m (s + 64) (sch_lk S) ->
  rw_cells rsegs m (s + 104) [C4 (wz 0); CB 1 [b8 1]; CB 3 j109] ->
  rw_cells rsegs m (s + 112) [CB 8 je] ->
  PCond m (s + 120) CLOCK_MONOTONIC ->
  rw_cells rsegs m (s + 168)
       [C8 (wz 0); C8 (wz 0); C8 (wz P_SCHED_GET_DEFAULT_TASK); C8 (wz 0); C8 (wz 0); C4 (wz 0); CB 4 jt;
        CB 3 [b8 1; b8 (sch_stopped S); b8 (sch_shutdown S)]; CB 5 j219; C8 (wz 0); C8 (wz 0); C8 (wz 0); C8 (wz u64max); C8 (wz u64max); C8 (wz 0)] ->
  rw_cells rsegs m (s + 272) (CookieCells j7) ->
  sv_vptr (sch_hdr S) = VP_SCHED -> sv_destroy (sch_hdr S) = P_DESTROY_ALLOC_SCHED ->
  (sch_stopped S = 0 \/ sch_stopped S = 1) -> (sch_shutdown S = 0 \/ sch_shutdown S = 1) ->
  Scheduler LB m s S.
Proof.
  intros LB m s S p j50 jm j109 je jt j219 j7 IN C0 C1 C2 PM C3 C4 PC C5 C6 E1 E2 E3 E4.
  exists p, j50, jm, j109, je, jt, j219, j7.
  unfold NEWSZ_SCH, SZ_SCH, O_SCH_ONE_THREAD, O_SCH_MUTEX, O_SCH_PMUTEX, O_SCH_SPIN, O_SCH_EVENT, O_SCH_COND, O_SCH_EVSTATE.
  repeat (split; [assumption|]). exact E4.
Qed.

Definition SCHED_SHUTDOWN_STACK : Z := 64 + MUTEX_UNLOCK_STACK.

Definition sch_shut (S : schv) : schv := mkSCH (sch_hdr S) 0 (sch_stopped S) 1.

Definition sched_shutdown_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (LB : list block) (s lo : Z) (S : schv) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom rsegs)
    /\ munch [(lo, bv_unsigned sp); (s, s + SZ_SCH)]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
    /\ stk rsegs m' lo (bv_unsigned sp)
    /\ Scheduler LB m' s (sch_shut S).

Definition sched_shutdown_stmt : Prop :=
  forall (s lo : Z) (LB : list block) (S : schv)
    ra sp gp tp t0 t1 t2 s0 s1 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  Scheduler LB m s S -> sch_lk S = 0 -> 0 < s -> s mod 16 = 0 -> s + NEWSZ_SCH <= hceil ->
  stk rsegs m lo (bv_unsigned sp) -> lo + SCHED_SHUTDOWN_STACK <= bv_unsigned sp -> hceil <= lo ->
  bv_unsigned sp mod 16 = 0 ->
  bv_unsigned ra mod 2 = 0 ->
  mem_inv rsegs m ->
  evt rsegs (sched_shutdown_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc LB s lo S m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz s) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_SCHED_SHUTDOWN) fc None m (seg_rom rsegs)).

